import requests
import time
import json
import base64

BASE_URL = "http://localhost:8000"
TIMEOUT = 30

# Minimal helper definitions to replace missing ts_helpers and fixture_payloads

def dev_jwt():
    # Return minimal dummy unsigned JWT with sub claim for dev environment
    header = base64.urlsafe_b64encode(json.dumps({"alg": "none", "typ": "JWT"}).encode()).rstrip(b"=").decode()
    payload = base64.urlsafe_b64encode(json.dumps({"sub": "test-user"}).encode()).rstrip(b"=").decode()
    # unsigned token with empty signature
    token = f"{header}.{payload}."
    return token

def auth_headers(token):
    return {"Authorization": f"Bearer {token}"}

def upload_bytes(file_bytes, filename, title, headers):
    # Use multipart/form-data upload according to the API
    files = {
        'file': (filename, file_bytes, 'application/pdf')
    }
    data = {'title': title}
    response = requests.post(f"{BASE_URL}/api/v1/ingest/upload", headers=headers, files=files, data=data, timeout=TIMEOUT)
    return response

def wait_indexed(source_id, headers, timeout=300, interval=5):
    # Poll /api/v1/ingest/sources until source_id is indexed or timeout
    deadline = time.time() + timeout
    while time.time() < deadline:
        resp = requests.get(f"{BASE_URL}/api/v1/ingest/sources", headers=headers, timeout=TIMEOUT)
        if resp.status_code != 200:
            time.sleep(interval)
            continue
        sources = resp.json().get('sources', [])
        for src in sources:
            if src.get('id') == source_id and src.get('status') == 'indexed':
                # indexed corresponds to ready
                if src.get('chunks_count', 0) > 0:
                    return True
        time.sleep(interval)
    return False

def stream_chat(url, headers, data, timeout=30):
    # Stream SSE events parsing generator
    with requests.post(url, headers=headers, json=data, stream=True, timeout=timeout) as resp:
        if resp.status_code != 200:
            raise AssertionError(f"Chat stream failed with status {resp.status_code}")
        buffer = ""
        for chunk in resp.iter_content(chunk_size=None):
            if not chunk:
                continue
            s = chunk.decode('utf-8')
            buffer += s
            while '\n\n' in buffer:
                event_str, buffer = buffer.split('\n\n', 1)
                event_lines = event_str.split('\n')
                event_dict = {}
                for line in event_lines:
                    if line.startswith('event: '):
                        event_dict['event'] = line[len('event: '):]
                    elif line.startswith('data: '):
                        event_dict['data'] = line[len('data: '):]
                if event_dict:
                    yield event_dict

# Minimal valid PDF bytes for upload (minimal header)
FIXTURES = {
    'standard_chapter.pdf': b'%PDF-1.4\n%EOF'
}

def test_RET_08_paraphrase_robustness():
    token = dev_jwt()
    headers = auth_headers(token)
    # Upload standard_chapter.pdf fixture and wait until indexed
    source_id = None
    try:
        # Upload the PDF from embedded fixture bytes
        upload_resp = upload_bytes(
            file_bytes=FIXTURES['standard_chapter.pdf'],
            filename='standard_chapter.pdf',
            title='standard_chapter.pdf',
            headers=headers
        )
        assert upload_resp.status_code == 200, f"Upload failed with status {upload_resp.status_code}"
        source_id = upload_resp.json().get('id')
        assert source_id, "Upload response missing source id"
        # Wait until source is indexed
        indexed = wait_indexed(source_id, headers, timeout=300)
        assert indexed, "Source did not reach indexed status in time"

        # Define three paraphrased chlorophyll questions
        questions = [
            "What role does chlorophyll play?",
            "Can you tell me about the function of chlorophyll?",
            "Explain the importance of chlorophyll in photosynthesis."
        ]

        # Collect sets of cited source_ids from SSE responses for each question
        citations_sets = []
        for question in questions:
            # chat stream request body
            data = {
                "message": question,
                "history": [],
                "active_source_ids": [source_id],
                "chat_id": ""
            }
            # Stream chat response and parse SSE events for citation source_ids
            cited_sources = set()
            for event in stream_chat(BASE_URL + "/api/v1/chat/stream", headers, data, timeout=TIMEOUT):
                # event is dict with 'event', 'data' keys expected
                if event.get('event') == 'citation':
                    try:
                        cit = json.loads(event.get('data', '{}'))
                        if 'source_id' in cit:
                            cited_sources.add(cit['source_id'])
                    except Exception:
                        # ignore malformed citation events
                        pass
                elif event.get('event') == 'done':
                    break
            assert cited_sources, f"No citations found for question: {question}"
            citations_sets.append(cited_sources)

        # Assert the citation source_ids overlap across all questions (non-empty intersection)
        common_citations = set.intersection(*citations_sets)
        assert common_citations, "Citation source_ids do not overlap across different phrasings"
    finally:
        if source_id:
            delete_resp = requests.delete(
                f"{BASE_URL}/api/v1/ingest/sources/{source_id}",
                headers=headers,
                timeout=TIMEOUT
            )
            assert delete_resp.status_code == 200 or delete_resp.status_code == 404, f"Failed to delete source {source_id}"


test_RET_08_paraphrase_robustness()
